function canMaster(role:Role,kind:string){return role==='admin'||({director:['people','companies'],gate:['people','fleet'],operations:['companies'],finance:[],reader:[]} as Record<string,string[]>)[role]?.includes(kind)}

function dt(v?:string,tz='America/Manaus',short=false){if(!v||Number.isNaN(+new Date(v)))return '—';return new Intl.DateTimeFormat('pt-BR',{timeZone:tz,day:'2-digit',month:'2-digit',...(short?{}:{year:'numeric'}),hour:'2-digit',minute:'2-digit'}).format(new Date(v))}
