function asIso(v:string,tz:string){if(!v)return '';const desired=new Date(`${v}:00Z`),zoned=new Date(localDate(desired.toISOString(),tz)+':00Z');return new Date(+desired+(+desired-+zoned)).toISOString()}
function duration(start:string,end?:string){const ms=Math.max(0,+(end?new Date(end):new Date())-+new Date(start)),h=Math.floor(ms/3600000);return h>=24?`${Math.floor(h/24)}d ${h%24}h`:`${h}h ${Math.floor(ms%3600000/60000)}min`}
function initials(s=''){return s.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'PG'}
function normalize(v:unknown){return String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function match(r:Row,q:string){return !q||normalize(Object.values(r).filter(v=>typeof v!=='object').join(' ')).includes(normalize(q))}
function csvSafe(v:unknown){const s=String(v??'');return '"'+(/^[\s]*[=+@-]/.test(s)?"'"+s:s).replace(/"/g,'""')+'"'}
function download(name:string,content:string,type:string){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function attemptKey(pending:Map<string,string>,signature:string){const existing=pending.get(signature);if(existing)return existing;const key=clientRequestId();pending.set(signature,key);return key}

