function Modal({title,children,onClose,wide=false}:{title:string;children:React.ReactNode;onClose:()=>void;wide?:boolean}){const ref=useRef<HTMLDivElement>(null),closeRef=useRef(onClose);closeRef.current=onClose;useEffect(()=>{const prior=document.activeElement as HTMLElement,before=document.body.style.overflow;document.body.style.overflow='hidden';setTimeout(()=>ref.current?.querySelector<HTMLElement>('input,select,textarea,button')?.focus(),30);const key=(e:KeyboardEvent)=>{if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const els=ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),a,input,textarea,select');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);document.body.style.overflow=before;prior?.focus()}},[]);return <div className="modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div role="dialog" aria-modal="true" aria-labelledby="dialog-title" className={`modal-dialog ${wide?'wide':''}`} ref={ref}><div className="modal-header"><h2 id="dialog-title" className="modal-title">{title}</h2><button className="close-button" onClick={onClose} aria-label="Fechar"><X size={20}/></button></div>{children}</div></div>}
