 const r=(kind==='detail'?collection?.find((x:Row)=>x.id===original.id):null)||original;
 const initial:Row={category:'visitor',...r,existingId:kind==='visitor'?(r.personId||''):'',gateName:state.settings.gateNames.includes(r.gateName)?r.gateName:state.settings.gateNames[0]||'',expectedAt:localDate(undefined,tz),validUntil:localDate(new Date(Date.now()+8*3600000).toISOString(),tz),reason:'',confirmation:'',role:r.role||'reader',status:r.status==='pending'?'active':r.status||'active'};
 if(kind==='master'&&masterKind==='people'&&capability(user,'accessManage')&&!r.id)initial.securityStatus='pending';
 if(kind==='correction'){Object.assign(initial,r);}
 const [seed]=useState(initial),[v,setV]=useState<Row>(seed),[error,setError]=useState(''),[saving,setSaving]=useState(false),[expectedRevision,setExpectedRevision]=useState(revision),[conflict,setConflict]=useState(false),[backup,setBackup]=useState<Row|null>(null),[fileName,setFileName]=useState('');
 const restoreKeys=useRef(new Map<string,string>()),approvers=useApprovers();
 const change=(name:string,value:any)=>{setError('');setV(prev=>{let next={...prev,[name]:value};if(name==='existingId'){if(kind==='visitor'){const p=state.people.find(p=>p.id===value);if(p)next={...next,name:p.name,company:p.company||'',host:p.host||'',category:p.category||'visitor',documentLast4:p.documentLast4||''}}if(kind==='vehicle'){const p=state.fleet.find(p=>p.id===value);if(p)next={...next,plate:p.plate,driver:p.driver||'',company:p.company||''}}}if(name==='areaId'&&kind==='visitor'){const area=(state.accessAreas||[]).find((area:Row)=>area.id===value);next={...next,responsibleUserId:area?.responsibleUserId||'',substituteUserId:area?.substituteUserId||''};const responsible=approvers.users.find((u:Row)=>u.id===area?.responsibleUserId);if(responsible)next.host=responsible.name}if(name==='responsibleUserId'){const responsible=approvers.users.find((u:Row)=>u.id===value);if(responsible)next.host=responsible.name;if(next.substituteUserId===value)next.substituteUserId=''}if(name==='driverPersonId'&&kind==='vehicle'){const person=state.people.find(p=>p.id===value);if(person)next={...next,driver:person.name}}return next})};
 const gate:FieldDef={name:'gateName',label:'Portaria',type:'select',required:true,options:state.settings.gateNames.map((s:string)=>({value:s,label:s}))};
